  app += [table(['Bridge item','USDm / million shares'],[['Basic shares',f'{c["basic_shares_m"]:,.6f}'],['Diluted shares',f'{c["shares_m"]:,.6f}'],['Current basic market capitalization',f'{r["current_equity_m"]:,.2f}'],['Current diluted capitalization',f'{r["diluted_equity_m"]:,.2f}'],['Cash and included short investments',f'{c["cash_m"]:,.2f}'],['Required/restricted operating reserve',f'{c.get("minimum_cash_m",0):,.2f}'],['Debt',f'{c["debt_m"]:,.2f}'],['Senior/noncommon claims',f'{c.get("senior_claims_m",0):,.2f}'],['Other assets, base',f'{c.get("other_assets_m",0):,.2f}'],['Current operating EV (reserve retained)',f'{r["current_ev_m"]:,.2f}'],['Conventional EV before minimum-cash reserve',f'{r["conventional_ev_m"]:,.2f}']])]
  if t=='GRSD':app += ['**Financing correction:** the cash-settlement base path has only $10.09m of quarter-end liquidity in June2027, even assuming all cash and unused commitments qualify, below the $15m covenant. The upside path also falls short. Returns below are conditional payoffs before an unmodeled cure, not financeable expected returns. A waiver, earlier refinancing or equity settlement is required under those assumptions; none is guaranteed. The reported June2026 position was compliant. See the dated liquidity checks in research/deep_neglected/valuations.json and the correction in its research appendix.\n']
  if t=='STLA':app += ['History below is consolidated Stellantis, including financial services; forward revenue/EBIT/FCFF is industrial only. The captive bank is valued separately on required-capital-adjusted equity distributions. Do not infer growth by directly comparing these different perimeters.\n']
